local syncedCount = 0
for _, item in ipairs(files) do
    local rootServiceName = item.path[1]
    local current: Instance = game:GetService(rootServiceName)
    for i = 2, #item.path - 1 do
        local seg = item.path[i]
        local child = current:FindFirstChild(seg)
        if not child then
            child = Instance.new("Folder")
            child.Name = seg
            child.Parent = current
        end
        current = child
    end

    local leafName = item.path[#item.path]
    local scriptObj = current:FindFirstChild(leafName)
    if not scriptObj or scriptObj.ClassName ~= item.class then
        if scriptObj then scriptObj:Destroy() end
        scriptObj = Instance.new(item.class)
        scriptObj.Name = leafName
        scriptObj.Parent = current
    end

    local sourceCode = decodeB64(item.b64)
    (scriptObj :: any).Source = sourceCode
    syncedCount = syncedCount + 1
end

return string.format("SYNC SUCCESS: Updated %d scripts in Studio DataModel.", syncedCount)